class Solution {
    public boolean canBeEqual(int[] target,int[] arr){
        Map<Integer,Integer> count=new HashMap<>();
        for(int value:target)count.merge(value,1,Integer::sum);
        for(int value:arr)count.merge(value,-1,Integer::sum);
        return count.values().stream().allMatch(value->value==0);
    }
}

code.kotlin:
class Solution {
    fun canBeEqual(target:IntArray,arr:IntArray):Boolean{
        val count=mutableMapOf<Int,Int>();
        for(value in target)count[value]=(count[value]?:0)+1;
        for(value in arr)count[value]=(count[value]?:0)-1;
        return count.values.all{
            it==0
        }
    }
}

